        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.diversityHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                tmtChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.diversityHistory },
