        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const diversity = Math.round(ds.diversity);
            const cohesion = Math.round(ds.cohesion);
            const readiness = Math.round(ds.readiness);
            const apac = ds.apac;
            const composite = Math.round(Math.min(100, (apac - this.START_APAC) / (this.APAC_TARGET - this.START_APAC) * 100) * 0.45 + diversity * 0.2 + cohesion * 0.2 + readiness * 0.15);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.hitTarget && s.balanced);
            const badge = met
                ? `<span class="tmtsim-cm-badge tmtsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="tmtsim-cm-badge tmtsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const riskBadge = s.fractured
                ? ` <span class="tmtsim-cm-badge tmtsim-cm-no">` + T(`cm_fractured`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const apacStr = (typeof s.apac === `number`) ? `CHF ` + Math.round(s.apac) + `M` : String(s.apac || ``);
            const metrics = ``
                + `<div class="tmtsim-cm-metric"><span class="tmtsim-cm-mv">` + Math.round(s.diversity || 0) + `</span><span class="tmtsim-cm-ml">` + T(`cm_m_diversity`) + `</span></div>`
                + `<div class="tmtsim-cm-metric"><span class="tmtsim-cm-mv">` + Math.round(s.cohesion || 0) + `</span><span class="tmtsim-cm-ml">` + T(`cm_m_cohesion`) + `</span></div>`
                + `<div class="tmtsim-cm-metric"><span class="tmtsim-cm-mv">` + Math.round(s.readiness || 0) + `</span><span class="tmtsim-cm-ml">` + T(`cm_m_readiness`) + `</span></div>`
                + `<div class="tmtsim-cm-metric"><span class="tmtsim-cm-mv">` + apacStr + `</span><span class="tmtsim-cm-ml">` + T(`cm_m_apac`) + `</span></div>`;
            return ``
                + `<div class="tmtsim-completion">`
                +   `<div class="tmtsim-cm-head">`
                +     `<div class="tmtsim-cm-score">` + score + `<span class="tmtsim-cm-score-max">/100</span></div>`
                +     `<div class="tmtsim-cm-grade">` + grade + ` ` + badge + riskBadge + `</div>`
                +   `</div>`
                +   `<div class="tmtsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="tmtsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="tmtsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const diversity = Math.round(ds.diversity);
            const cohesion = Math.round(ds.cohesion);
            const readiness = Math.round(ds.readiness);
            const apac = ds.apac;

            const hitTarget = apac >= this.APAC_TARGET;
            const balanced = diversity >= 45 && cohesion >= 55 && readiness >= 60;
            const fractured = ds.fractured || cohesion < 45;
            const blind = diversity < 35;
            const composite = Math.round(Math.min(100, (apac - this.START_APAC) / (this.APAC_TARGET - this.START_APAC) * 100) * 0.45 + diversity * 0.2 + cohesion * 0.2 + readiness * 0.15);

            let performanceKey = `grade_stalled`;
            if (hitTarget && balanced) performanceKey = `grade_delivered`;
            else if (apac >= 560 && balanced) performanceKey = `grade_credible`;
            else if (fractured) performanceKey = `grade_collapse`;
            else if (blind) performanceKey = `grade_blind`;
            else if (apac > this.START_APAC + 150) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && balanced) insights.push(window.mySimulation.t(`insight_delivered`));
            else if (fractured) insights.push(window.mySimulation.t(`insight_fractured`));
            else if (blind) insights.push(window.mySimulation.t(`insight_blind`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (diversity >= 45 && cohesion < 45) insights.push(window.mySimulation.t(`insight_index_vanity`));
            if (cohesion >= 70 && diversity < 35) insights.push(window.mySimulation.t(`insight_cohesion_trap`));
            if (ds.seatsAdded > this.MAX_ADDED || ds.budgetUsed > this.BUDGET_CAP + 0.001) insights.push(window.mySimulation.t(`insight_overcap`));
            if (hitTarget && balanced && cohesion >= 65) insights.push(window.mySimulation.t(`insight_converts`));

            return {
                diversity: diversity,
                cohesion: cohesion,
                readiness: readiness,
                apac: apac,
                hitTarget: hitTarget,
                fractured: fractured,
                balanced: balanced,
                blind: blind,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.fractured) return window.mySimulation.t(`hint_fractured`);
            if (ds.diversity < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_blind`);
            if (ds.cohesion < 50 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_integrate`);
            if (state.currentPeriod >= 3 && ds.apac < 420) return window.mySimulation.t(`hint_behind`);
            if (ds.apac >= this.APAC_TARGET && ds.cohesion >= 60 && ds.diversity >= 45) return window.mySimulation.t(`hint_strong`);
            return null;
        }

